// The Worker's entry point (wrangler.jsonc "main"): the OpenNext build of the
// app (.open-next/worker.js, written by `opennextjs-cloudflare build`) plus
// the Cron Trigger, which runs the reminder code directly (./cron.ts) every 15 minutes.

// Generated by the build, so it is missing before one.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import openNext from '../.open-next/worker.js'
import { scheduledReminders } from './cron'
import { healthCheck } from './health'

type Env = CloudflareEnv
type FetchHandler = { fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> }

const app = openNext as FetchHandler

export default {
  fetch(request, env, ctx) {
    return healthCheck(request) ?? app.fetch(request, env, ctx)
  },

  async scheduled(_controller, env) {
    await scheduledReminders(env)
  },
} satisfies ExportedHandler<Env>
